const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arabianSea = ee.Geometry.Polygon([
    [
      [50.0, 5.0],  // SW corner near Somalia
      [50.0, 25.0], // NW corner near Oman/Iran
      [75.0, 25.0], // NE corner near Pakistan/India
      [75.0, 5.0],  // SE corner off the coast of India
      [50.0, 5.0]
    ]
  ]);
  const startDate = '2023-06-01';
  const endDate = '2023-06-30';

  // 2. Data Acquisition
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2.1')
    .filterDate(startDate, endDate)
    .filterBounds(arabianSea)
    .select('sst');

  const collectionSize = sstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Evidence: No images found for the specified date and location.");
    console.log("A: Yes"); // Placeholder answer, will not be reached
    console.log("B: No"); // Placeholder answer, will not be reached
    console.log("C1: Empty Collection");
    return;
  }
  console.log(`Image collection size: ${collectionSize}`);

  // 3. Processing
  // Create a single image representing the maximum temperature at each pixel over the month.
  // The scale factor of 0.01 converts the band's stored values to degrees Celsius.
  const maxSSTImage = sstCollection.max().multiply(0.01);

  // 4. Calculation
  // Find the maximum temperature within the entire geometry for the month.
  const scale = 30000; // OISST is a coarse resolution dataset (0.25 degree)
  const reduction = maxSSTImage.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: arabianSea,
    scale: scale,
    maxPixels: 1e9
  });

  const stats = reduction.getInfo();
  const maxTemp = stats['sst_max'];
  const pixelCount = stats['sst_count'];

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("Evidence: No valid pixels found in the region after processing.");
    console.log("A: Yes"); // Placeholder answer, will not be reached
    console.log("B: No"); // Placeholder answer, will not be reached
    console.log("C2: No Valid Pixels");
    return;
  }

  if (maxTemp === null || typeof maxTemp === 'undefined') {
    console.log("Evidence: Calculation failed, result is null.");
    console.log("A: Yes"); // Placeholder answer, will not be reached
    console.log("B: No"); // Placeholder answer, will not be reached
    console.log("C3: Calculation Failure");
    return;
  }

  const threshold = 30.0;
  const conditionMet = maxTemp >= threshold;

  console.log(`Region: Arabian Sea`);
  console.log(`Period: ${startDate} to ${endDate}`);
  console.log(`Maximum SST found: ${maxTemp.toFixed(2)} C`);
  console.log(`Valid pixel count: ${pixelCount}`);
  console.log(`Threshold for 'Yes': >= ${threshold} C`);

  if (conditionMet) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
